-- ===================== VERIFY =====================
-- Every row below should show ok = 1
SELECT i.invoice_number, i.period_start, i.paid_date, ip.payment_date,
       (i.paid_date = ip.payment_date) AS dates_agree
FROM invoices i
JOIN placements p ON p.id = i.placement_id AND p.status = 'Active'
LEFT JOIN invoice_payments ip ON ip.invoice_id = i.id
WHERE i.paid_date IS NOT NULL
ORDER BY i.period_start;